import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import './AttendancePage.css'; // We'll still use our custom CSS
import axios from 'axios';

// This is a SIMULATION of what your backend API for time logs will provide.
// The keys are 'employee_id-date_string'.
const mockTimeLogsAPI = {
  '1-2025-10-01': { clockIn: '09:05', clockOut: '17:15' },
  '1-2025-10-02': { clockIn: '09:10', clockOut: '17:00' },
  '1-2025-10-03': { clockIn: '09:00', clockOut: '13:00' }, // Half Day
  '1-2025-10-06': { status: 'On Leave' },
  '1-2025-10-08': { status: 'Absent' },
  '2-2025-10-01': { clockIn: '08:55', clockOut: '17:05' },
  // ... more data
};

const AttendancePage = () => {
  const [employees, setEmployees] = useState([]); // To populate the dropdown
  const [selectedEmployeeId, setSelectedEmployeeId] = useState('');
  const [date, setDate] = useState(new Date());
  const [attendanceData, setAttendanceData] = useState({}); // To hold the logs for the selected user

  // 1. Fetch the list of all employees to populate the dropdown
  useEffect(() => {
    const fetchEmployees = async () => {
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = response.data.results || response.data || [];
        setEmployees(employeesData);
        if (employeesData.length > 0) {
          setSelectedEmployeeId(employeesData[0].id); // Select the first employee by default
        }
      } catch (error) {
        console.error("Failed to fetch employees:", error);
      }
    };
    fetchEmployees();
  }, []);

  // 2. Fetch attendance data whenever the selected employee or the month changes
  useEffect(() => {
    if (!selectedEmployeeId) return;

    const fetchAttendanceForEmployee = () => {
      console.log(`Fetching attendance for employee ${selectedEmployeeId} for month ${date.getMonth() + 1}`);
      // --- REAL API CALL WOULD GO HERE ---
      // e.g., axios.get(`/api/timelogs/?employee=${selectedEmployeeId}&month=${...}`)
      // For now, we simulate by filtering our mock API data
      const userLogs = {};
      for (const key in mockTimeLogsAPI) {
        if (key.startsWith(`${selectedEmployeeId}-`)) {
          const dateString = key.split('-').slice(1).join('-');
          userLogs[dateString] = mockTimeLogsAPI[key];
        }
      }
      setAttendanceData(userLogs);
    };
    fetchAttendanceForEmployee();
  }, [selectedEmployeeId, date]); // Re-run this when the user or date changes

  // 3. This function calculates the status based on time data
  const getDayStatus = (log) => {
    if (log?.status === 'On Leave') return 'On Leave';
    if (log?.status === 'Absent') return 'Absent';
    if (log?.clockIn && log.clockOut) {
      const inTime = new Date(`1970-01-01T${log.clockIn}:00`);
      const outTime = new Date(`1970-01-01T${log.clockOut}:00`);
      const hoursWorked = (outTime - inTime) / (1000 * 60 * 60);
      return hoursWorked < 5 ? 'Half Day' : 'Present';
    }
    if (log?.clockIn) return 'Present'; // Still present if not clocked out yet
    return null;
  };

  const tileClassName = ({ date, view }) => {
    if (view === 'month') {
      const dateString = date.toISOString().slice(0, 10);
      const log = attendanceData[dateString];
      const status = getDayStatus(log);
      if (status) {
        return `day-${status.toLowerCase().replace(' ', '-')}`;
      }
    }
    return null;
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold">Attendance Calendar</h1>
          <p className="text-sm text-subtext-light">View monthly attendance based on time tracking data.</p>
        </div>
        {/* 4. The Employee Selector Dropdown */}
        <div className="w-full max-w-xs">
          <label htmlFor="employee-select" className="text-sm font-medium text-subtext-light">Select Employee</label>
          <select 
            id="employee-select"
            value={selectedEmployeeId}
            onChange={(e) => setSelectedEmployeeId(e.target.value)}
            className="w-full mt-1"
          >
            {employees.map(emp => (
              <option key={emp.id} value={emp.id}>
                {emp.firstName} {emp.lastName}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-4 rounded-xl shadow-sm">
        <Calendar
          onChange={setDate}
          value={date}
          tileClassName={tileClassName}
          className="w-full border-none"
        />
      </div>

      {/* Legend for the calendar colors */}
      <div className="mt-4 flex justify-center space-x-4">
          <span className="flex items-center text-sm"><span className="legend-dot day-present"></span> Present</span>
          <span className="flex items-center text-sm"><span className="legend-dot day-half-day"></span> Half Day</span>
          <span className="flex items-center text-sm"><span className="legend-dot day-on-leave"></span> On Leave</span>
          <span className="flex items-center text-sm"><span className="legend-dot day-absent"></span> Absent</span>
      </div>
    </div>
  );
};

export default AttendancePage;
